constexpr bool isHostLittleEndian() { return (std::endian::native == std::endian::little); }
constexpr bool isHostBigEndian() { return (std::endian::native == std::endian::big); }

namespace TiffCraft {
  template <typename T>
  bool operator==(const RationalT<T>& lhs, const RationalT<T>& rhs) {
    return lhs.numerator == rhs.numerator && lhs.denominator == rhs.denominator;
  }
}

template <typename T>
bool operator==(const std::span<const T>& lhs, const std::span<const T>& rhs) {
  return lhs.size() == rhs.size() && std::equal(lhs.begin(), lhs.end(), rhs.begin());
}

template <typename T>
std::span<const T> make_span(std::initializer_list<T> values) {
  return std::span<const T>(values.begin(), values.size());
}

std::string getTestFilePath(const std::string& filename) {
  std::filesystem::path test_file_path(__FILE__);
  std::filesystem::path test_dir = test_file_path.parent_path();
  return (test_dir / "libtiff-pics" / filename).string();
}

std::ostream& write_IFD_entry(
  std::ostream& os,
  Tag tag,
  Type type,
  uint32_t count,
  const std::byte* values,
  uint32_t valueOffset = 0,
  bool mustSwap = false)
{
  const uint32_t valueBytes = count * typeBytes(type);

  // Current position in the stream
  const uint32_t startPos = static_cast<uint32_t>(os.tellp());

  if (count < 1) {
    throw std::runtime_error("Count must be at least 1");
  }
  if (values == nullptr) {
    throw std::runtime_error("Values pointer cannot be null");
  }
  if (valueOffset - startPos < 12 && valueOffset != 0) {
    throw std::runtime_error("Value offset must be zero or greater or equal to 12");
  }
  if (valueBytes > 4 && valueOffset == 0) {
    throw std::runtime_error("Value offset must be provided if values do not fit in 4 bytes");
  }
  if (valueBytes <= 4 && valueOffset > 0) {
    throw std::runtime_error("Value offset must be zero if values fit in 4 bytes");
  }
  if (valueOffset % 2 != 0) {
    throw std::runtime_error("Value offset must be even");
  }

  writeValue(os, tag, mustSwap);
  writeValue(os, type, mustSwap);
  writeValue(os, count, mustSwap);

  if (valueBytes <= 4) {
    // Values fit in 4 bytes, write them directly
    std::vector<std::byte> valueBytesVec(4, std::byte{0});
    std::copy(values, values + valueBytes, valueBytesVec.data());
    if (mustSwap) {
      // Note that we swap values as an array, instead of as a single `uint32_t`
      // This is because the values may not be a single `uint32_t` but rather
      // a sequence of smaller types (e.g., uint16_t, uint8_t)
      swapArray(valueBytesVec.data(), type, count);
    }
    os.write(reinterpret_cast<const char*>(valueBytesVec.data()), 4);
  }
  else {
    // Values do not fit in 4 bytes, write the offset
    writeValue(os, valueOffset, mustSwap);
    std::streampos offset = static_cast<std::streampos>(valueOffset);
    if (mustSwap) {
      std::vector<std::byte> swappedValues(values, values+valueBytes);
      swapArray(swappedValues.data(), type, count);
      writeAt(os, offset, swappedValues.data(), valueBytes);
    }
    else {
      writeAt(os, offset, values, valueBytes);
    }
  }

  return os;
}

std::ostream& write_IFD(
  std::ostream& os,
  const std::vector<TiffImage::IFD::Entry>& entries,
  bool mustSwap = false)
{
  // We write the IFD first, and the entry data afterwards. Therefore, we need
  // calculate the offsets of the entries first.
  const uint32_t IFD_bytes = 2 + 12 * entries.size(); // 2 bytes for the count,
                                                      // and 12 bytes per entry

  // Current position in the stream
  std::streampos currentPos = os.tellp();

  uint32_t nextOffset = IFD_bytes + static_cast<uint32_t>(currentPos);
  std::vector<uint32_t> offsets;
  offsets.reserve(entries.size());
  for (const auto& entry : entries) {
    if (entry.bytes() > 4) {
      // If the entry value does not fit in 4 bytes, we need to write it at a later offset
      offsets.emplace_back(nextOffset);
      nextOffset += entry.bytes();
    }
    else {
      // If the entry value fits in 4 bytes, we can write it directly
      offsets.emplace_back(0);
    }
  }

  // Write the number of entries
  writeValue(os, static_cast<uint16_t>(entries.size()), mustSwap);

  // Write the entries
  for (const auto& entry : entries) {
    write_IFD_entry(os, entry.tag(), entry.type(), entry.count(),
      entry.values(), offsets[&entry - &entries[0]], mustSwap);
  }

  return os;
}

TEST_CASE("TiffImage Header class") {

  std::cout << "TiffCraft version: " << TiffCraft::version() << std::endl;

  // Define the expected structure of the TIFF header
  // It should be 8 bytes in total:
  struct HeaderBytes {
      uint16_t byteOrder;       // 0x4949 for "II", 0x4D4D for "MM"
      uint16_t magicNumber;     // 42
      uint32_t firstIFDOffset;  // Offset of the first IFD

      HeaderBytes(uint16_t bo = 0x4949, uint16_t mn = 42, uint32_t ifdOffset = 8)
          : byteOrder(bo), magicNumber(mn), firstIFDOffset(ifdOffset)
      {
        if (std::endian::native == std::endian::little && bo == 0x4D4D // "MM" big-endian
            || std::endian::native == std::endian::big && bo == 0x4949) { // "II" little-endian
          magicNumber = std::byteswap(magicNumber);
          firstIFDOffset = std::byteswap(firstIFDOffset);
        }
      }

      std::ostream& write(std::ostream& os) const {
        auto startPos = os.tellp();
        os.write(reinterpret_cast<const char*>(&byteOrder), sizeof(byteOrder));
        os.write(reinterpret_cast<const char*>(&magicNumber), sizeof(magicNumber));
        os.write(reinterpret_cast<const char*>(&firstIFDOffset), sizeof(firstIFDOffset));
        auto endPos = os.tellp();
        if (endPos - startPos != sizeof(HeaderBytes)) {
          throw std::runtime_error("HeaderBytes size mismatch");
        }
        return os;
      }
  };

  { // Test little-endian header
    HeaderBytes headerBytes{ 0x4949, 42, 8 };
    std::stringstream stream;
    headerBytes.write(stream);

    TiffImage::Header header = TiffImage::Header::read(stream);
    CHECK(header.byteOrder() == std::endian::little);
    CHECK(header.equalsHostByteOrder() == isHostLittleEndian());
  }

  { // Test big-endian header
    HeaderBytes headerBytes{ 0x4D4D, 42, 8 };
    std::stringstream stream;
    headerBytes.write(stream);

    TiffImage::Header header = TiffImage::Header::read(stream);
    CHECK(header.byteOrder() == std::endian::big);
    CHECK(header.equalsHostByteOrder() == isHostBigEndian());
  }

  { // Test wrong byte order
    HeaderBytes headerBytes{ 0x4D49, 42, 8 };
    std::stringstream stream;
    headerBytes.write(stream);
    // This should throw an exception due to invalid byte order
    CHECK_THROWS_AS(TiffImage::Header::read(stream), std::runtime_error);
  }

  { // Test wrong magic number
    HeaderBytes headerBytes{ 0x4949, 43, 8 }; // Magic number should be 42
    std::stringstream stream;
    headerBytes.write(stream);
    // This should throw an exception due to invalid magic number
    CHECK_THROWS_AS(TiffImage::Header::read(stream), std::runtime_error);
  }

  { // Test wrong offset
    HeaderBytes headerBytes{ 0x4949, 43, 7 }; // Offset should be >= 8
    std::stringstream stream;
    headerBytes.write(stream);
    // This should throw an exception due to invalid first IFD offset
    CHECK_THROWS_AS(TiffImage::Header::read(stream), std::runtime_error);
  }

  { // Test invalid stream
    std::stringstream stream;
    // This should throw an exception due to invalid stream
    CHECK_THROWS_AS(TiffImage::Header::read(stream), std::runtime_error);
  }

  { // fax2d.tif: big-endian
    const std::string test_file = "fax2d.tif";
    std::cout << "Test file path: " << getTestFilePath(test_file) << std::endl;
    std::ifstream file(getTestFilePath(test_file), std::ios::binary);
    CHECK(file.is_open());
    CHECK(file.good());
    auto header = TiffImage::Header::read(file);
    std::cout << header << std::endl;
  }
}

TEST_CASE("TiffImage IFD::Entry class") {

  auto testEntry = [](
      uint16_t tagInt, Type type, uint32_t count,
      const std::vector<uint8_t>& values,
      uint32_t valueOffset = 0, bool mustSwap = false) {

    std::stringstream stream;
    write_IFD_entry(
      stream, static_cast<Tag>(tagInt), type, count,
      reinterpret_cast<const std::byte*>(values.data()),
      valueOffset, mustSwap);

    TiffImage::IFD::Entry entry = TiffImage::IFD::Entry::read(stream, mustSwap);

    const Tag tag = static_cast<Tag>(tagInt);

    CHECK(entry.tag() == tag);
    CHECK(entry.type() == type);
    CHECK(entry.count() == count);
    CHECK(entry.bytes() == count * TiffCraft::typeBytes(type));
    CHECK(entry.values() != nullptr);

    const std::byte* valuePtr = entry.values();
    for (uint32_t i = 0; i < entry.bytes(); ++i) {
      CHECK(valuePtr[i] == static_cast<std::byte>(values[i]));
    }
  };

  // Test with BYTE type
  testEntry(0x0101, Type::BYTE, 1, { 0x01 });
  testEntry(0x0101, Type::BYTE, 2, { 0x01, 0x02 });
  testEntry(0x0101, Type::BYTE, 3, { 0x01, 0x02, 0x03 });
  testEntry(0x0101, Type::BYTE, 4, { 0x01, 0x02, 0x03, 0x04 });
  testEntry(0x0101, Type::BYTE, 5, { 0x01, 0x02, 0x03, 0x04, 0x05 }, 12);
  testEntry(0x0101, Type::BYTE, 6, { 0x01, 0x02, 0x03, 0x04, 0x05, 0x06 }, 20);

  // Test with SHORT type
  testEntry(0x0102, Type::SHORT, 1, { 0x01, 0x02 });
  testEntry(0x0102, Type::SHORT, 1, { 0x01, 0x02 }, 0, true); // Must swap
  testEntry(0x0102, Type::SHORT, 2, { 0x01, 0x02, 0x03, 0x04 });
  testEntry(0x0102, Type::SHORT, 2, { 0x01, 0x02, 0x03, 0x04 }, 0, true); // Must swap
  testEntry(0x0102, Type::SHORT, 3, { 0x01, 0x02, 0x03, 0x04, 0x05, 0x06 }, 18);
  testEntry(0x0102, Type::SHORT, 4, { 0x01, 0x02, 0x03, 0x04, 0x05, 0x06, 0x07, 0x08 }, 20, true); // Must swap

  // Test with LONG type
  testEntry(0x0103, Type::LONG, 1, { 0x01, 0x02, 0x03, 0x04 });
  testEntry(0x0103, Type::LONG, 1, { 0x01, 0x02, 0x03, 0x04 }, 0, true); // Must swap
  testEntry(0x0103, Type::LONG, 2, { 0x01, 0x02, 0x03, 0x04, 0x05, 0x06, 0x07, 0x08 }, 22);
  testEntry(0x0103, Type::LONG, 3, { 0x01, 0x02, 0x03, 0x04, 0x05, 0x06, 0x07, 0x08, 0x09, 0x0A, 0x0B, 0x0C }, 22, true); // Must swap

  // Test with RATIONAL type
  testEntry(0x0104, Type::RATIONAL, 1, { 0x01, 0x02, 0x03, 0x04, 0x05, 0x06, 0x07, 0x08 }, 12);
  testEntry(0x0104, Type::RATIONAL, 1, { 0x01, 0x02, 0x03, 0x04, 0x05, 0x06, 0x07, 0x08 }, 12, true); // Must swap
  testEntry(0x0104, Type::RATIONAL, 2, { 0x01, 0x02, 0x03, 0x04, 0x05, 0x06, 0x07, 0x08,
                                         0x09, 0x0A, 0x0B, 0x0C, 0x0D, 0x0E, 0x0F, 0x10 }, 24);

  // Test with ASCII type
  testEntry(0x0105, Type::ASCII, 1, { '\0' });
  testEntry(0x0105, Type::ASCII, 2, { 'A', '\0' });
  testEntry(0x0105, Type::ASCII, 3, { 'A', 'B', '\0' });
  testEntry(0x0105, Type::ASCII, 4, { 'A', 'B', 'C', '\0' });
  testEntry(0x0105, Type::ASCII, 5, { 'A', 'B', 'C', 'D', '\0' }, 12);
  testEntry(0x0105, Type::ASCII, 6, { 'A', 'B', 'C', 'D', 'E', '\0' }, 16);
}

TEST_CASE("TiffImage IFD class") {

  // Create a few entries
  std::vector<TiffImage::IFD::Entry> entries;
  {
    auto addEntry = [&entries](
      uint16_t tag, Type type, uint32_t count,
      const std::vector<uint8_t>& values,
      uint32_t valueOffset = 0, bool mustSwap = false) {
        std::stringstream stream;
        // Write the entry
        write_IFD_entry(
          stream, static_cast<Tag>(tag), type, count,
          reinterpret_cast<const std::byte*>(values.data()),
          valueOffset, mustSwap);
        // Read the entry back
        TiffImage::IFD::Entry entry = TiffImage::IFD::Entry::read(stream, mustSwap);
        // Add the entry to the vector
        entries.push_back(entry);
    };
    addEntry(0x0101, Type::BYTE, 6, { 0x01, 0x02, 0x03, 0x04, 0x05, 0x06 }, 12);
    addEntry(0x0102, Type::SHORT, 1, { 0x01, 0x02 });
    addEntry(0x0103, Type::LONG, 2, { 0x01, 0x02, 0x03, 0x04, 0x05, 0x06, 0x07, 0x08 }, 12);
    addEntry(0x0104, Type::RATIONAL, 1, { 0x01, 0x02, 0x03, 0x04, 0x05, 0x06, 0x07, 0x08 }, 12);
    addEntry(0x0105, Type::ASCII, 6, { 'A', 'B', 'C', 'D', 'E', '\0' }, 12);
  }
  CHECK(entries.size() == 5);

  { // Test writing and reading IFD
    std::stringstream stream;
    write_IFD(stream, entries, false);

    // Read the IFD back
    TiffImage::IFD ifd = TiffImage::IFD::read(stream, false);

    // Check the number of entries
    CHECK(ifd.entries().size() == entries.size());

    // Check each entry
    auto it = ifd.entries().begin();
    for (size_t i = 0; i < entries.size(); ++i, ++it) {
      CHECK(it->second == entries[i]);
    }
  }
}

TEST_CASE("TiffImage class") {

  { // jim___ah.tif
    // Dimensions: 664x813
    // Resolution: 300 DPI
    // Bit depth: 1
    // Compression: Uncompressed
    // Resolution unit: 2
    const std::string test_file = "jim___ah.tif";
    std::cout << "Test file path: " << getTestFilePath(test_file) << std::endl;
    TiffImage image = TiffImage::read(getTestFilePath(test_file));
    std::cout << image << std::endl;

    const auto& ifds = image.ifds();
    CHECK(ifds.size() == 1);

    const auto& entries = ifds[0].entries();
    CHECK(entries.size() == 14);

    #define value_span(type, tag) entries.at(tag).values<type>()
    #define Eq(a, b) std::equal(a.begin(), a.end(), b.begin())

    CHECK(Eq(value_span(uint16_t, Tag::ImageWidth), make_span<uint16_t>({ 664 })));
    CHECK(Eq(value_span(uint16_t, Tag::ImageLength), make_span<uint16_t>({ 813 })));
    CHECK(Eq(value_span(uint16_t, Tag::Compression), make_span<uint16_t>({ 1 })));
    CHECK(Eq(value_span(uint16_t, Tag::PhotometricInterpretation), make_span<uint16_t>({ 0 })));
    CHECK(Eq(value_span(Rational, Tag::XResolution), make_span({ Rational{300, 1} })));
    CHECK(Eq(value_span(Rational, Tag::YResolution), make_span({ Rational{300, 1} })));

    #undef Eq
    #undef value_span

    auto imageData = image.readImageStrips(image.stream(), ifds[0]);
    constexpr size_t expectedImageDataSize = 664 * 813 / 8; // 1 bit per pixel
    size_t actualImageDataSize = 0;
    for (const auto& data : imageData) {
      actualImageDataSize += data.size();
    }
    CHECK(actualImageDataSize == expectedImageDataSize);
  }

  { // jim___ah.tif: using load function
    const std::string test_file = "jim___ah.tif";
    std::cout << "Test file path: " << getTestFilePath(test_file) << std::endl;
    load(getTestFilePath(test_file),
      [](const TiffImage::Header& header, const TiffImage::IFD& ifd, TiffImage::ImageData imageData) {
        std::cout << "Loaded IFD with " << ifd.entries().size() << " entries." << std::endl;
        std::cout << "Image data size: " << imageData.size() << std::endl;

        const auto& entries = ifd.entries();

        #define value_span(type, tag) entries.at(tag).values<type>()
        #define Eq(a, b) std::equal(a.begin(), a.end(), b.begin())

        CHECK(Eq(value_span(uint16_t, Tag::ImageWidth), make_span<uint16_t>({ 664 })));
        CHECK(Eq(value_span(uint16_t, Tag::ImageLength), make_span<uint16_t>({ 813 })));
        CHECK(Eq(value_span(uint16_t, Tag::Compression), make_span<uint16_t>({ 1 })));
        CHECK(Eq(value_span(uint16_t, Tag::PhotometricInterpretation), make_span<uint16_t>({ 0 })));
        CHECK(Eq(value_span(Rational, Tag::XResolution), make_span({ Rational{300, 1} })));
        CHECK(Eq(value_span(Rational, Tag::YResolution), make_span({ Rational{300, 1} })));

        #undef Eq
        #undef value_span

        constexpr size_t expectedImageDataSize = 664 * 813 / 8; // 1 bit per pixel
        size_t actualImageDataSize = 0;
        for (const auto& data : imageData) { actualImageDataSize += data.size(); }
        CHECK(actualImageDataSize == expectedImageDataSize);
      }
    );
  }

  { // cramps-tile.tif: using load function
    const std::string test_file = "cramps-tile.tif";
    std::cout << "Test file path: " << getTestFilePath(test_file) << std::endl;
    load(getTestFilePath(test_file),
      [](const TiffImage::Header& header, const TiffImage::IFD& ifd, TiffImage::ImageData imageData) {
        std::cout << "Loaded IFD with " << ifd.entries().size() << " entries." << std::endl;
        std::cout << "Image data size: " << imageData.size() << std::endl;

        const auto& entries = ifd.entries();

        #define value_span(type, tag) entries.at(tag).values<type>()
        #define Eq(a, b) std::equal(a.begin(), a.end(), b.begin())

        CHECK(Eq(value_span(uint16_t, Tag::ImageWidth), make_span<uint16_t>({ 800 })));
        CHECK(Eq(value_span(uint16_t, Tag::ImageLength), make_span<uint16_t>({ 607 })));
        CHECK(Eq(value_span(uint16_t, Tag::Compression), make_span<uint16_t>({ 1 })));
        CHECK(Eq(value_span(uint16_t, Tag::PhotometricInterpretation), make_span<uint16_t>({ 0 })));
        CHECK(Eq(value_span(uint16_t, Tag::TileWidth), make_span<uint16_t>({ 256 })));
        CHECK(Eq(value_span(uint16_t, Tag::TileLength), make_span<uint16_t>({ 256 })));
        CHECK(Eq(value_span(uint16_t, Tag::SamplesPerPixel), make_span<uint16_t>({ 1 })));
        CHECK(Eq(value_span(uint16_t, Tag::BitsPerSample), make_span<uint16_t>({ 8 })));

        #undef Eq
        #undef value_span

        constexpr size_t tilesAcross = (800 + (256 - 1)) / 256;
        constexpr size_t tilesDown = (607 + (256 - 1)) / 256;
        constexpr size_t tilesInImage = tilesAcross * tilesDown;
        CHECK(imageData.size() == tilesInImage);

        constexpr size_t expectedTileSize = 256 * 256;
        for (const auto& tile : imageData) {
          CHECK(tile.size() == expectedTileSize);
        }
      }
    );
  }
}

TEST_CASE("Malformed TIFF input") {

  { // (a) ASCII entry with count == 0
    std::stringstream stream;
    writeValue(stream, static_cast<uint16_t>(0x4949), false); // "II"
    writeValue(stream, static_cast<uint16_t>(42), false);     // Magic number
    writeValue(stream, static_cast<uint32_t>(8), false);      // First IFD offset
    // IFD at offset 8
    writeValue(stream, static_cast<uint16_t>(1), false);                      // 1 entry
    writeValue(stream, static_cast<uint16_t>(Tag::ImageDescription), false);  // Tag
    writeValue(stream, static_cast<uint16_t>(Type::ASCII), false);            // Type
    writeValue(stream, static_cast<uint32_t>(0), false);                      // Count == 0
    writeValue(stream, static_cast<uint32_t>(0), false);                      // Inline value
    writeValue(stream, static_cast<uint32_t>(0), false);                      // Next IFD offset
    CHECK_THROWS_AS(TiffImage::read(stream), std::runtime_error);
  }

  { // (b) Cyclic IFD offset
    std::stringstream stream;
    writeValue(stream, static_cast<uint16_t>(0x4949), false); // "II"
    writeValue(stream, static_cast<uint16_t>(42), false);     // Magic number
    writeValue(stream, static_cast<uint32_t>(8), false);      // First IFD offset
    // IFD at offset 8: 0 entries, next IFD offset points back to itself
    writeValue(stream, static_cast<uint16_t>(0), false);      // 0 entries
    writeValue(stream, static_cast<uint32_t>(8), false);      // Next IFD offset (cyclic)
    CHECK_THROWS_AS(TiffImage::read(stream), std::runtime_error);
  }

  { // (c) Truncated strip: strip data is missing from the stream
    std::vector<TiffImage::IFD::Entry> entries;
    auto addEntry = [&entries](
      uint16_t tag, Type type, uint32_t count,
      const std::vector<uint8_t>& values,
      uint32_t valueOffset = 0, bool mustSwap = false) {
        std::stringstream stream;
        // Write the entry
        write_IFD_entry(
          stream, static_cast<Tag>(tag), type, count,
          reinterpret_cast<const std::byte*>(values.data()),
          valueOffset, mustSwap);
        // Read the entry back
        TiffImage::IFD::Entry entry = TiffImage::IFD::Entry::read(stream, mustSwap);
        // Add the entry to the vector
        entries.push_back(entry);
    };
    // Entries must be sorted in ascending tag order
    addEntry(0x0103, Type::SHORT, 1, { 1 });                  // Compression = none
    addEntry(0x0106, Type::SHORT, 1, { 0 });                  // PhotometricInterpretation = WhiteIsZero
    addEntry(0x0111, Type::LONG, 1, { 100, 0, 0, 0 });        // StripOffsets = 100 (beyond end of stream)
    addEntry(0x0117, Type::LONG, 1, { 232, 3, 0, 0 });        // StripByteCounts = 1000

    std::stringstream stream;
    writeValue(stream, static_cast<uint16_t>(0x4949), false); // "II"
    writeValue(stream, static_cast<uint16_t>(42), false);     // Magic number
    writeValue(stream, static_cast<uint32_t>(8), false);      // First IFD offset
    // IFD at offset 8 (only the IFD; the strip data is not written)
    write_IFD(stream, entries, false);
    writeValue(stream, static_cast<uint32_t>(0), false);      // Next IFD offset
    CHECK_THROWS_AS(
      load(stream, [](auto&&...) { }, LoadParams{}),
      std::runtime_error);
  }

  { // (d) RATIONAL entry with a zero denominator
    std::stringstream stream;
    writeValue(stream, static_cast<uint16_t>(0x4949), false); // "II"
    writeValue(stream, static_cast<uint16_t>(42), false);     // Magic number
    writeValue(stream, static_cast<uint32_t>(8), false);      // First IFD offset
    // IFD at offset 8
    writeValue(stream, static_cast<uint16_t>(1), false);                 // 1 entry
    writeValue(stream, static_cast<uint16_t>(Tag::XResolution), false);  // Tag
    writeValue(stream, static_cast<uint16_t>(Type::RATIONAL), false);    // Type
    writeValue(stream, static_cast<uint32_t>(1), false);                 // Count
    writeValue(stream, static_cast<uint32_t>(26), false);                // Value offset (after the IFD table)
    writeValue(stream, static_cast<uint32_t>(0), false);                 // Next IFD offset (offset 22)
    // RATIONAL value at offset 26: numerator = 300, denominator = 0
    writeValue(stream, static_cast<uint32_t>(300), false);               // Numerator
    writeValue(stream, static_cast<uint32_t>(0), false);                 // Denominator
    // Entry::read does not divide rationals, so reading the image must not throw
    TiffImage image = TiffImage::read(stream);
    REQUIRE(image.ifds().size() == 1);
    CHECK_THROWS_AS(TiffExporter::getIntVec(image.ifds()[0], Tag::XResolution), std::runtime_error);
  }
}

TEST_CASE("LONG ImageWidth fixtures") {

  auto checkFixture = [](const std::string& filename, uint32_t expectedWidth, uint32_t expectedLength) {
    const std::string test_file = filename;
    std::cout << "Test file path: " << getTestFilePath(test_file) << std::endl;
    TiffImage image = TiffImage::read(getTestFilePath(test_file));

    const auto& entries = image.ifds().at(0).entries();

    const auto widthIt = entries.find(Tag::ImageWidth);
    REQUIRE(widthIt != entries.end());
    CHECK(widthIt->second.type() == Type::LONG);
    CHECK(widthIt->second.values<uint32_t>()[0] == expectedWidth);
    // LONG entries do not fit the 16-bit accessor (documents the D6 defect class)
    CHECK_THROWS_AS(widthIt->second.values<uint16_t>(), std::runtime_error);

    const auto lengthIt = entries.find(Tag::ImageLength);
    REQUIRE(lengthIt != entries.end());
    CHECK(lengthIt->second.type() == Type::LONG);
    CHECK(lengthIt->second.values<uint32_t>()[0] == expectedLength);
    CHECK_THROWS_AS(lengthIt->second.values<uint16_t>(), std::runtime_error);
  };

  checkFixture("pc260001.tif", 640, 480);
  checkFixture("smallliz.tif", 160, 160);
}

TEST_CASE("Type::BYTE printed as integer") {

  const std::vector<uint8_t> values{ 0x41 }; // 65 ('A')
  std::stringstream stream;
  write_IFD_entry(
    stream, Tag::ImageWidth, Type::BYTE, 1,
    reinterpret_cast<const std::byte*>(values.data()));

  TiffImage::IFD::Entry entry = TiffImage::IFD::Entry::read(stream, false);

  std::ostringstream ss;
  ss << entry;
  CHECK(ss.str().find("65") != std::string::npos);
  CHECK(ss.str().find("'A'") == std::string::npos);
}

# Changelog

All notable changes to this project will be documented in this file.

The format is based on [Keep a Changelog](https://keepachangelog.com/en/1.1.0/),
and this project adheres to [Semantic Versioning](https://semver.org/spec/v2.0.0.html).

Given a version number MAJOR.MINOR.PATCH, increment the:

    MAJOR version when you make incompatible API changes.
    MINOR version when you add functionality in a backward compatible manner.
    PATCH version when you make backward compatible bug fixes.

## [0.2.0-Unreleased]

### Added

- Code examples
- README now documents which headers are needed and the copy-only
  consumption path (header-only; copy the headers into the project, no build
  step required).
- CMake consumption improvements: added the `TiffCraft::TiffCraft` namespaced
  alias, an installable/exportable target with generated
  `TiffCraftConfig.cmake`/`TiffCraftConfigVersion.cmake` (for `find_package`),
  and a `TIFFCRAFT_BUILD_ALL` option that defaults to `ON` when building
  TiffCraft standalone and to `OFF` when consumed via `FetchContent` or
  `add_subdirectory`.

### Fixed

- `TiffExporter.hpp` no longer includes the umbrella header `TiffCraft.hpp`;
  it now includes `TiffImage.hpp` directly, resolving the include cycle and
  making the exporter header standalone.
- ODR violations in headers: `inline` on `version()`, `readAt()`, `writeAt()`,
  and both `load()` overloads (`TiffImage.hpp`); the six `operator<<` overloads
  moved into `namespace TiffCraft` and marked `inline` (`TiffStdOut.hpp`).
  Note: the stream operators are no longer visible in the global namespace;
  they are found via ADL, which applies to all TiffCraft types.
- Crash/hang fixes for malformed TIFF input: ASCII entry with count 0 no
  longer reads out of bounds (throws `std::runtime_error`); RATIONAL/SRATIONAL
  entries with a zero denominator no longer divide by zero (throws
  `std::runtime_error`); cyclic IFD offsets are detected and rejected (throws
  `std::runtime_error`).
- `readAt()` now detects short reads and throws `std::runtime_error`, so
  truncated strips/tiles no longer silently yield zero-filled buffers.
- `takeImage()` no longer copies instead of moving; it moves the image buffer
  out of the exporter, leaving it empty.
- `TiffExporterAny` now resets its multi-IFD state per IFD; each IFD is
  exported and the last successfully exported image wins (previously later
  IFDs were silently skipped).
- Example `tiff_image` reads `ImageWidth`/`ImageLength` type-agnostically, so
  LONG-typed entries no longer throw.
- README quick-start snippet fixed (removed undeclared `loadParams` argument;
  fixed `iffExporter` typo).
- `Type::BYTE` entries print as integers instead of raw characters.

## [0.1.0]

### Added

- Initial TiffCraft code for loading TIFF images and exporter for bilevel,
  grayscale, palette-color, and RGB images. Compression is not supported.
- Example `tiff_exporter` program to convert TIFF images to PNG 8-bit format.

### Changed

- Moved all headers to `include/tiffcraft`.
---WORKFLOW---
name: Build and Test

on:
  push:
    branches: [ main ]
  pull_request:
    branches: [ main ]  # on pull requests to main branch
  workflow_dispatch:    # manually trigger the workflow

permissions:
  checks: write
  actions: read
  contents: read

jobs:

  build-linux:
    name: Ubuntu-Build
    runs-on: ubuntu-latest

    env:
      PRESET_NAME: gcc-linux-release

    steps:
    - name: Checkout source code
      uses: actions/checkout@v5.0.0

    - name: Checkout submodules
      run: git submodule update --init --recursive

    - name: Cmake configure
      run: cmake --preset ${{ env.PRESET_NAME }} ${{ env.CMAKE_CONFIG_OPTIONS }}

    - name: Cmake build
      run: cmake --build --preset "${{ env.PRESET_NAME }}" -j

    - name: Run Tests
      run: ctest --preset ${{ env.PRESET_NAME }} --output-on-failure

  build-linux-consumers:
    name: Ubuntu-Consumers
    runs-on: ubuntu-latest

    steps:
    - name: Checkout source code
      uses: actions/checkout@v5.0.0

    - name: Checkout submodules
      run: git submodule update --init --recursive

    - name: Cmake configure
      run: cmake --preset gcc-linux-release -DCMAKE_INSTALL_PREFIX=/tmp/opencode/tiffcraft-install

    - name: Cmake build
      run: cmake --build --preset gcc-linux-release -j

    - name: Cmake install
      run: cmake --build --preset gcc-linux-release --target install

    - name: FindPackage consumer
      run: |
        cmake -S tests/cmake-consumers/findpackage -B /tmp/opencode/build-fpkg -DCMAKE_PREFIX_PATH=/tmp/opencode/tiffcraft-install
        cmake --build /tmp/opencode/build-fpkg -j
        /tmp/opencode/build-fpkg/findpackage_consumer

    - name: FetchContent consumer
      run: |
        cmake -S tests/cmake-consumers/fetchcontent -B /tmp/opencode/build-fc
        cmake --build /tmp/opencode/build-fc -j
        /tmp/opencode/build-fc/fetchcontent_consumer

    - name: Subdirectory consumer
      run: |
        cmake -S tests/cmake-consumers/subdirectory -B /tmp/opencode/build-sub
        cmake --build /tmp/opencode/build-sub -j
        /tmp/opencode/build-sub/subdirectory_consumer

  build-windows:
    name: Windows-Build
    runs-on: windows-2025

    env:
      PRESET_NAME: msvc-win64-ninja-release

    steps:
    - name: Checkout source code
      uses: actions/checkout@v5.0.0

    - name: Checkout submodules
      run: git submodule update --init --recursive

    - name: Set up MSVC environment
      uses: ilammy/msvc-dev-cmd@v1

    - name: Cmake configure
      run: cmake --preset ${{ env.PRESET_NAME }} ${{ env.CMAKE_CONFIG_OPTIONS }}

    - name: Cmake build
      run: cmake --build --preset "${{ env.PRESET_NAME }}" -j

    - name: Run Tests
      run: ctest --preset ${{ env.PRESET_NAME }} --output-on-failure

  build-macos:
    name: MacOS-Build
    runs-on: macos-15

    env:
      PRESET_NAME: clang-macos-ninja-release

    steps:
    - name: Checkout source code
      uses: actions/checkout@v5.0.0

    - name: Checkout submodules
      run: git submodule update --init --recursive

    - name: Cmake configure
      run: cmake --preset ${{ env.PRESET_NAME }} ${{ env.CMAKE_CONFIG_OPTIONS }}

    - name: Cmake build
      run: cmake --build --preset "${{ env.PRESET_NAME }}" -j

    - name: Run Tests
      run: ctest --preset ${{ env.PRESET_NAME }} --output-on-failure
